{"results": [{"id": "hp_doc_d805a981392a25f30f7a7e9db2dddb5bb7dcb0cfdffeac52a24eb33d36c4d8a1", "title": "Albert Mohler", "text": "Richard Albert Mohler Jr. (born October 19, 1959), is an American historical theologian and the ninth president of the Southern Baptist Theological Seminary in Louisville, Kentucky. He has been described as \"one of America's most influential evangelicals\".", "score": 37.8856}, {"id": "hp_doc_b8be06704f5974093296b528e469c76d8c0f1e34ae8951674120c1909c660a7d", "title": "Richard Muller (theologian)", "text": "Richard A. Muller (born October 12, 1948, in Flushing, New York) is an American historical theologian.", "score": 20.8084}, {"id": "hp_doc_08783905bcf355cbbfee0cc5ef223b17230ccb9a17931c836c4bd552cf8595f5", "title": "KCFO", "text": "KCFO (970 AM) is a Tulsa, Oklahoma, area Christian radio station. KCFO airs national shows such as Dave Ramsey, J. Vernon McGee, David Jeremiah, Dennis Rainey, and Albert Mohler.", "score": 18.098}], "remaining_searches": 1}
